{
  "name": "mdtracker",
  "version": "1.4.1",
  "description": "OpenCode TUI sidebar plugin that tracks Markdown context metrics (chars / tokens).",
  "type": "module",
  "license": "MIT",
  "author": "xiaolf <xiaolf1@126.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/xiaolf1/MdTracker.git"
  },
  "homepage": "https://github.com/xiaolf1/MdTracker",
  "bugs": {
    "url": "https://github.com/xiaolf1/MdTracker/issues"
  },
  "main": "./dist/server.js",
  "types": "./dist/server.d.ts",
  "exports": {
    ".": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.jsx"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "config": {
        "enabled": true
      }
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.jsx",
      "config": {
        "enabled": true,
        "sidebar": true
      }
    }
  },
  "scripts": {
    "clean": "rimraf dist",
    "build": "npm run clean && tsc",
    "test": "npm run build",
    "prepublishOnly": "npm run build"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "sidebar",
    "markdown",
    "tiktoken",
    "context"
  ],
  "dependencies": {
    "gpt-tokenizer": "^2.5.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.2.0",
    "@opentui/core": ">=0.3.4",
    "@opentui/solid": ">=0.3.4",
    "solid-js": "^1.8.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.3.2",
    "@opentui/core": ">=0.3.4",
    "@opentui/solid": ">=0.3.4",
    "rimraf": "^5.0.0",
    "solid-js": "^1.8.0",
    "typescript": "^5.5.0",
    "@types/node": "^20.0.0"
  },
  "engines": {
    "opencode": ">=1.3.13"
  }
}
